theorem arch_present_of_arch_independent {C : Type u} [AddCommMonoid C] {F : Type v}
    [AddCommMonoid F] {E : Type w} [Monoid E] {P : Type*} [AddCommMonoid P] [PartialOrder P]
    (spec : CarrierSpec C F E P) : ∃ a : C, spec.archPart a ≠ 0

theorem signedCompletion_trivial_of_idempotent {M : Type u} [AddCommMonoid M] {G : Type v}
    [AddCommGroup G] (ι : M →+ G) (hcomp : IsSignedCompletion M G ι) (hidem : IdempotentAdd M)
    (g : G) : g = 0

theorem trivial_of_idempotent_of_spec {C : Type u} [AddCommMonoid C] {F : Type v}
    [AddCommMonoid F] {E : Type w} [Monoid E] {P : Type*} [AddCommMonoid P] [PartialOrder P]
    (spec : CarrierSpec C F E P) (hidem : IdempotentAdd C) (a : C) : a = 0

